const valorMinimoCupom = dadosCupom.property_pedido_m_nimo;

// 3. Chama a função aprimorada.
const resultadoDaAnalise = analisarValorMinimo(totalGeral, valorMinimoCupom);

// 4. Adiciona os resultados ao JSON de saída para serem usados nos próximos nós.
$json.cupomAtingiuMinimo = resultadoDaAnalise.atingeMinimo; // Retorna true ou false
$json.valorFaltante = resultadoDaAnalise.valorFaltante.toFixed(2); // Retorna o valor numérico, ex: "15.50"

// (Bônus) Adiciona uma versão já formatada para o cliente.
$json.valorFaltanteFormatado = resultadoDaAnalise.valorFaltante.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }); // Retorna "R$ 15,50"

// Retorna o item com as novas propriedades.
return $json;

